def seed(apps, schema_editor):
    Page = apps.get_model('studio', 'ContentPage')
    Text = apps.get_model('studio', 'ContentText')
    alias = schema_editor.connection.alias
    for scope, name, key, label, text, order in CONTENT:
        page, _ = Page.objects.using(alias).get_or_create(key=scope, defaults={'name': name})
        Text.objects.using(alias).get_or_create(key=key, defaults={'page': page, 'label': label, 'text': text, 'default_text': text, 'order': order})


